CREATE TYPE "ImportFormat" AS ENUM ('freehub', 'corsizio');
CREATE TYPE "ImportDisposition" AS ENUM ('create', 'existing_match', 'rejected');
ALTER TABLE "Person" ADD COLUMN "emailOptOut" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "street1" VARCHAR(255), ADD COLUMN "street2" VARCHAR(255), ADD COLUMN "city" VARCHAR(120), ADD COLUMN "state" VARCHAR(120), ADD COLUMN "postalCode" VARCHAR(40), ADD COLUMN "country" CHAR(2), ADD COLUMN "yearOfBirth" SMALLINT, ADD COLUMN "archivedByUserId" BIGINT, ADD COLUMN "createdByUserId" BIGINT, ADD COLUMN "updatedByUserId" BIGINT;
ALTER TABLE "Visit" ADD COLUMN "createdByUserId" BIGINT, ADD COLUMN "updatedByUserId" BIGINT;
ALTER TABLE "Service" ADD COLUMN "paid" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "volunteered" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "createdByUserId" BIGINT, ADD COLUMN "updatedByUserId" BIGINT;
ALTER TABLE "MigrationIssue" ADD COLUMN "resolvedByUserId" BIGINT, ADD COLUMN "resolvedAt" TIMESTAMP(3);
CREATE TABLE "Tag" ("id" BIGSERIAL PRIMARY KEY, "organizationId" BIGINT NOT NULL REFERENCES "Organization"("id"), "name" VARCHAR(120) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("organizationId", "name"));
CREATE TABLE "PersonTag" ("id" BIGSERIAL PRIMARY KEY, "organizationId" BIGINT NOT NULL, "personId" BIGINT NOT NULL REFERENCES "Person"("id") ON DELETE CASCADE, "tagId" BIGINT NOT NULL REFERENCES "Tag"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("personId", "tagId"));
CREATE TABLE "Note" ("id" BIGSERIAL PRIMARY KEY, "organizationId" BIGINT NOT NULL, "personId" BIGINT REFERENCES "Person"("id") ON DELETE CASCADE, "visitId" BIGINT REFERENCES "Visit"("id") ON DELETE CASCADE, "serviceId" BIGINT REFERENCES "Service"("id") ON DELETE CASCADE, "text" TEXT NOT NULL, "createdByUserId" BIGINT, "updatedByUserId" BIGINT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "note_one_target" CHECK ((CASE WHEN "personId" IS NULL THEN 0 ELSE 1 END + CASE WHEN "visitId" IS NULL THEN 0 ELSE 1 END + CASE WHEN "serviceId" IS NULL THEN 0 ELSE 1 END) = 1));
CREATE TABLE "PersonArchiveEvent" ("id" BIGSERIAL PRIMARY KEY, "organizationId" BIGINT NOT NULL REFERENCES "Organization"("id"), "personId" BIGINT NOT NULL REFERENCES "Person"("id") ON DELETE CASCADE, "actorUserId" BIGINT NOT NULL, "action" VARCHAR(12) NOT NULL CHECK ("action" IN ('archive', 'restore')), "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reason" TEXT);
CREATE TABLE "ImportJob" ("id" BIGSERIAL PRIMARY KEY, "organizationId" BIGINT NOT NULL REFERENCES "Organization"("id"), "format" "ImportFormat" NOT NULL, "sourceSha256" CHAR(64) NOT NULL, "status" VARCHAR(16) NOT NULL, "createdByUserId" BIGINT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "appliedAt" TIMESTAMP(3), UNIQUE("organizationId", "sourceSha256"));
CREATE TABLE "ImportRow" ("id" BIGSERIAL PRIMARY KEY, "importJobId" BIGINT NOT NULL REFERENCES "ImportJob"("id") ON DELETE CASCADE, "rowNumber" INTEGER NOT NULL, "disposition" "ImportDisposition" NOT NULL, "matchedPersonId" BIGINT, "createdPersonId" BIGINT, "matchReason" VARCHAR(80), "warnings" JSONB NOT NULL, "errors" JSONB NOT NULL, "inputFingerprint" CHAR(64) NOT NULL, UNIQUE("importJobId", "rowNumber"));
